package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	raw := "  order_id=1024, amount=19.90, paid=true  "

	parts := strings.Split(strings.TrimSpace(raw), ",")
	fmt.Println("字段数:", len(parts))

	var b strings.Builder
	for _, p := range parts {
		key, value, ok := strings.Cut(strings.TrimSpace(p), "=")
		if ok {
			b.WriteString(strings.ToLower(key))
			b.WriteString("=")
			b.WriteString(value)
			b.WriteString(";")
		}
	}
	fmt.Println("整理后:", b.String())

	for _, p := range parts {
		key, value, ok := strings.Cut(strings.TrimSpace(p), "=")
		if !ok {
			continue
		}
		if strings.EqualFold(key, "order_id") {
			id, err := strconv.Atoi(value)
			if err != nil {
				fmt.Println("订单号解析失败:", err)
				continue
			}
			fmt.Printf("订单号 %d，十六进制 %s\n", id, strconv.FormatInt(int64(id), 16))
		} else if strings.EqualFold(key, "amount") {
			amount, err := strconv.ParseFloat(value, 64)
			if err != nil {
				fmt.Println("金额解析失败:", err)
				continue
			}
			fmt.Printf("金额 %.2f\n", amount)
		} else if strings.EqualFold(key, "paid") {
			paid, err := strconv.ParseBool(value)
			if err != nil {
				fmt.Println("布尔解析失败:", err)
				continue
			}
			fmt.Println("是否已支付:", paid)
		}
	}

	fmt.Println("键值对数量:", strings.Count(b.String(), "="))
	fmt.Println(strings.NewReplacer("order_id", "订单号").Replace(b.String()))
	fmt.Println(strconv.Quote("订单已提交"))
	fmt.Println(strings.Repeat("-", 20))
}
